void ApplyMigrations(AppDbContext db)
{
    // EF Core 9 disallows Migrate() inside a user transaction;
    // it manages its own transactions internally.
    var strategy = db.Database.CreateExecutionStrategy();
    strategy.Execute(() =>
    {
        db.Database.Migrate();
    });
}

