using Microsoft.EntityFrameworkCore;

// Cosmos DB provider – EF Core 9 breaking changes applied:
//
// 1. Discriminator property: EF Core 9 changed the default JSON property
//    from "Discriminator" to "$type". Existing documents still store
//    "Discriminator", so we pin the old name to avoid data mismatch.
//
// 2. Synchronous queries: The Cosmos provider no longer supports sync I/O.
//    All queries must use async (ToListAsync, FirstOrDefaultAsync, etc.).

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Pin the discriminator JSON property name to match existing documents
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Example: async-only query pattern (sync .ToList() no longer compiles with Cosmos)
class ProductService
{
    private readonly CosmosContext _db;
    public ProductService(CosmosContext db) => _db = db;

    // BEFORE (EF Core 8 – sync, now throws at runtime in EF Core 9):
    //   var products = _db.Products.Where(p => p.Name == name).ToList();
    //
    // AFTER (EF Core 9 – must be async):
    public async Task<List<Product>> GetByNameAsync(string name)
    {
        return await _db.Products
            .Where(p => p.Name == name)
            .ToListAsync();
    }
}

